/**
 * Personal API tokens. Only the `hashToken()` digest of a secret is stored, and
 * no function here returns it: rows leave this module as `ApiToken` values.
 */
import { and, asc, count, desc, eq, gt, isNull, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { apiTokens, getDb } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toApiToken } from "./_mappers";
import type { ApiToken, ApiTokenScope } from "@/types/api-token";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";

export interface NewApiToken {
  readonly orgId: OrgId;
  readonly userId: UserId;
  readonly name: string;
  readonly scope: ApiTokenScope;
  readonly prefix: string;
  readonly tokenHash: string;
  readonly expiresAt: IsoTimestamp;
  readonly createdAt: IsoTimestamp;
}

/**
 * Counts the user's usable tokens (not revoked, not yet expired at
 * `token.createdAt`) and inserts in one transaction, so concurrent creations
 * cannot slip past `limit`. Returns `null`, storing nothing, when the user is
 * already at the limit.
 */
export async function insertApiTokenWithinLimit(
  token: NewApiToken,
  limit: number,
): Promise<ApiToken | null> {
  return getDb().transaction((tx) => {
    const usable = tx
      .select({ value: count() })
      .from(apiTokens)
      .where(
        and(
          orgPredicate(apiTokens.orgId, token.orgId),
          eq(apiTokens.userId, token.userId),
          isNull(apiTokens.revokedAt),
          gt(apiTokens.expiresAt, token.createdAt),
        ),
      )
      .get();

    if ((usable?.value ?? 0) >= limit) return null;

    const row = tx
      .insert(apiTokens)
      .values({
        id: newId(),
        orgId: token.orgId,
        userId: token.userId,
        name: token.name,
        scope: token.scope,
        prefix: token.prefix,
        tokenHash: token.tokenHash,
        expiresAt: token.expiresAt,
        lastUsedAt: null,
        revokedAt: null,
        createdAt: token.createdAt,
      })
      .returning()
      .get();

    return toApiToken(row);
  });
}

export async function findApiTokenById(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return row ? toApiToken(row) : null;
}

/**
 * Authentication runs before any tenant is known, so this is one of the reads
 * that is not scoped by `orgId` — the secret's hash is the credential and
 * carries the tenant with it.
 */
export async function findApiTokenByHash(
  tokenHash: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();
  return row ? toApiToken(row) : null;
}

/** Every token of one user in one org, revoked and expired included, newest first. */
export async function listApiTokens(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(
      and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.userId, userId)),
    )
    // Rows created in the same millisecond keep their insertion order.
    .orderBy(desc(apiTokens.createdAt), desc(sql`${apiTokens}.rowid`))
    .all();

  return rows.map(toApiToken);
}

/**
 * Stamps `revokedAt` on a token that is still unrevoked. Resolves `null` when
 * there was nothing to revoke (unknown id, or already revoked), which is how
 * the caller tells "I revoked it" from "it was already revoked".
 */
export async function markApiTokenRevoked(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<ApiToken | null> {
  const row = getDb()
    .update(apiTokens)
    .set({ revokedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .get();
  return row ? toApiToken(row) : null;
}

/** Revokes every not-yet-revoked token (expired ones included) of one user in one org. */
export async function revokeUnrevokedApiTokensForUser(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .update(apiTokens)
    .set({ revokedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .all();

  return rows
    .map(toApiToken)
    .sort((a, b) => a.createdAt.localeCompare(b.createdAt));
}

export async function touchApiTokenLastUsed(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(apiTokens)
    .set({ lastUsedAt: at })
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .run();
}

