/**
 * Personal API tokens: issue, list, revoke and authenticate. Only the hash of a secret is stored; the secret is returned once, by `createApiToken`.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, subscribe, hashToken, randomToken, resolveActor
 */
import { emit, subscribe } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { createApiTokenSchema } from "@/schemas/api-token";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { apiTokenResource, envelope, actorEnvelope, requireFound } from "./_support";
import { resolveActor } from "./member-service";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

/** How many usable (unrevoked, unexpired) tokens one user may hold per organization. */
const MAX_USABLE_TOKENS = 5;

const SECRET_PREFIX = "tfk_";

/** Length of `ApiToken.prefix`: the leading characters of the secret. */
const PREFIX_LENGTH = 12;

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * Mints a token for the actor. The secret comes back exactly once, in `token`;
 * `apiToken` (and everything published about it) carries no trace of it.
 */
export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);

  assertOrgScope(actor, parsed.orgId);
  const resource = apiTokenResource(parsed.orgId, actor.userId);
  assertCan(actor, "api_token:create", resource);
  if (parsed.scope === "write") {
    assertCan(actor, "api_token:create_write", resource);
  }

  const token = `${SECRET_PREFIX}${randomToken()}`;
  const now = new Date();

  const apiToken = await apiTokenRepo.insertApiTokenWithinLimit(
    {
      orgId: parsed.orgId,
      userId: actor.userId,
      name: parsed.name,
      scope: parsed.scope,
      prefix: token.slice(0, PREFIX_LENGTH),
      tokenHash: hashToken(token),
      expiresAt: toIsoTimestamp(
        new Date(now.getTime() + parsed.expiresInDays * MS_PER_DAY),
      ),
      createdAt: toIsoTimestamp(now),
    },
    MAX_USABLE_TOKENS,
  );

  if (apiToken === null) {
    throw new Error(
      `A user may hold at most ${MAX_USABLE_TOKENS} active API tokens per organization; revoke one first`,
    );
  }

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    ownerId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
    expiresAt: apiToken.expiresAt,
  });

  return { token, apiToken };
}

/**
 * The user's tokens in the organization — revoked and expired included —
 * newest first. Anyone may list their own; listing another user's needs an
 * admin, which `api_token:manage` expresses as "admin, or the token's owner".
 */
export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId: UserId = actor.userId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "api_token:manage", apiTokenResource(orgId, userId));

  return apiTokenRepo.listApiTokens(orgId, userId);
}

/**
 * Revoking is idempotent: a token that is already revoked comes back as it
 * was, with its original `revokedAt`, and nothing is audited a second time.
 */
export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const existing = requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "API token",
    tokenId,
  );
  assertCan(actor, "api_token:manage", apiTokenResource(orgId, existing.userId));

  if (existing.revokedAt !== null) return existing;

  const revoked = await apiTokenRepo.markApiTokenRevoked(
    orgId,
    tokenId,
    toIsoTimestamp(new Date()),
  );
  // Lost a race with another revocation: it audited the revoke, not us.
  if (revoked === null) {
    return requireFound(
      await apiTokenRepo.findApiTokenById(orgId, tokenId),
      "API token",
      tokenId,
    );
  }

  await emitRevoked(revoked, actorEnvelope(actor));
  return revoked;
}

/**
 * Resolves a presented secret to the `Actor` it acts as, or `null`. A `read`
 * token always acts as a viewer; a `write` token acts with the member's role
 * as it is right now, so promotions and demotions apply immediately.
 */
export async function authenticateApiToken(
  token: string,
): Promise<Actor | null> {
  const stored = await apiTokenRepo.findApiTokenByHash(hashToken(token));
  if (stored === null || stored.revokedAt !== null) return null;

  const now = toIsoTimestamp(new Date());
  if (stored.expiresAt <= now) return null;

  const org = await orgRepo.findOrgById(stored.orgId);
  if (org === null || org.archivedAt !== null) return null;

  const member = await resolveActor(stored.userId, stored.orgId);
  if (member === null) return null;

  await apiTokenRepo.touchApiTokenLastUsed(stored.orgId, stored.id, now);

  return {
    userId: member.userId,
    orgId: member.orgId,
    role: stored.scope === "read" ? "viewer" : member.role,
  };
}

