 * Attaches the handlers this service owns. Called once from
 * `event-registry`; the returned function detaches them all.
 *
 * A removed member's tokens stop working on their own (`authenticateApiToken`
 * re-checks membership), but they are also revoked and audited, so the list
 * never shows a live-looking token for someone who is gone.
 */
export function registerApiTokenListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("member.removed", async (payload) => {
      const revoked = await apiTokenRepo.revokeUnrevokedApiTokensForUser(
        payload.orgId,
        payload.userId,
        toIsoTimestamp(new Date()),
      );

      for (const apiToken of revoked) {
        await emitRevoked(apiToken, envelope(payload.orgId, payload.actorId));
      }
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

function emitRevoked(
  apiToken: ApiToken,
  stamp: ReturnType<typeof envelope>,
): Promise<void> {
  return emit("api_token.revoked", {
    ...stamp,
    tokenId: apiToken.id,
    ownerId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
  });
}

