/**
 * Personal API tokens: issuing, the five-token allowance, listing, revoking,
 * authenticating, the audit trail and the member-removal cascade.
 *
 * Runs with the app's event wiring attached (`registerEventHandlers()`), the
 * way `instrumentation.ts` starts it.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { ZodError } from "zod";
import { hashToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { activityFilterSchema } from "@/schemas/activity";
import { getDb } from "@/server/db";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { listActivity } from "@/server/services/activity-service";
import {
  authenticateApiToken,
  createApiToken,
  listApiTokens,
  revokeApiToken,
} from "@/server/services/api-token-service";
import {
  registerEventHandlers,
  unregisterEventHandlers,
} from "@/server/services/event-registry";
import { removeMember, updateMemberRole } from "@/server/services/member-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { ApiTokenScope } from "@/types/api-token";
import type { Actor } from "@/types/member";

const DAY_MS = 24 * 60 * 60 * 1000;

let cleanup: () => void;
let slugCounter = 0;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

afterEach(() => {
  vi.useRealTimers();
});

function newTenant(): Promise<Tenant> {
  slugCounter += 1;
  return createTenant(`tokens-${slugCounter}`, "growth");
}

function input(
  tenant: Tenant,
  overrides: Partial<{ name: string; scope: ApiTokenScope; expiresInDays: number }> = {},
) {
  return {
    orgId: tenant.org.id,
    name: overrides.name ?? "ci",
    scope: overrides.scope ?? ("read" as const),
    expiresInDays: overrides.expiresInDays ?? 30,
  };
}

async function auditRows(tenant: Tenant, actor: Actor = tenant.actors.admin) {
  const page = await listActivity(actor, {
    orgId: tenant.org.id,
    subjectKind: "api_token",
    limit: 100,
    cursor: null,
  });
  return page.items;
}

describe("createApiToken", () => {
  it("returns the secret once, alongside a token that carries neither secret nor hash", async () => {
    const tenant = await newTenant();
    const now = new Date("2030-01-01T00:00:00.000Z");
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(now);

    const { token, apiToken } = await createApiToken(
      tenant.actors.member,
      input(tenant, { name: "  deploy  ", scope: "write", expiresInDays: 10 }),
    );

    expect(token).toMatch(/^tfk_[A-Za-z0-9_-]+$/);
    expect(apiToken).toEqual({
      id: expect.any(String),
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      name: "deploy",
      scope: "write",
      prefix: token.slice(0, 12),
      expiresAt: new Date(now.getTime() + 10 * DAY_MS).toISOString(),
      lastUsedAt: null,
      revokedAt: null,
      createdAt: now.toISOString(),
    });

    const serialized = JSON.stringify(apiToken);
    expect(serialized).not.toContain(token);
    expect(serialized).not.toContain(hashToken(token));
  });

  it("stores only a hash of the secret", async () => {
    const tenant = await newTenant();
    const { token, apiToken } = await createApiToken(tenant.actors.viewer, input(tenant));

    const rows = getDb()
      .$client.prepare("SELECT * FROM api_tokens WHERE id = ?")
      .all(apiToken.id) as Record<string, unknown>[];

    expect(rows).toHaveLength(1);
    expect(rows[0]?.token_hash).toBe(hashToken(token));
    expect(JSON.stringify(rows[0])).not.toContain(token);
  });

  it("rejects invalid input with the ZodError and stores nothing", async () => {
    const tenant = await newTenant();
    const bad = [
      { ...input(tenant), name: "   " },
      { ...input(tenant), name: "x".repeat(81) },
      { ...input(tenant), scope: "admin" },
      { ...input(tenant), expiresInDays: 0 },
      { ...input(tenant), expiresInDays: 366 },
      { ...input(tenant), expiresInDays: 1.5 },
      { ...input(tenant), orgId: "not-a-ulid" },
    ];

    for (const candidate of bad) {
      await expect(
        createApiToken(tenant.actors.member, candidate as never),
      ).rejects.toBeInstanceOf(ZodError);
    }

    expect(await listApiTokens(tenant.actors.member, tenant.org.id)).toHaveLength(0);
  });

  it("requires the input org to be the actor's org", async () => {
    const tenant = await newTenant();
    const other = await newTenant();

    await expect(
      createApiToken(tenant.actors.member, input(other)),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("lets any role create a read token but only member and above a write token", async () => {
    const tenant = await newTenant();

    for (const role of ["viewer", "member", "admin", "owner"] as const) {
      await createApiToken(tenant.actors[role], input(tenant, { scope: "read" }));
    }

    await expect(
      createApiToken(tenant.actors.viewer, input(tenant, { scope: "write" })),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    for (const role of ["member", "admin", "owner"] as const) {
      await createApiToken(tenant.actors[role], input(tenant, { scope: "write" }));
    }
  });

  it("caps usable tokens at five per user and organization", async () => {
    const tenant = await newTenant();
    const actor = tenant.actors.member;

    const created = [];
    for (let i = 0; i < 5; i += 1) {
      created.push(await createApiToken(actor, input(tenant, { name: `t${i}` })));
    }

    await expect(createApiToken(actor, input(tenant))).rejects.toThrow();
    expect(await listApiTokens(actor, tenant.org.id)).toHaveLength(5);

    // Other users have their own allowance.
    await createApiToken(tenant.actors.admin, input(tenant));

    // A revoked token frees a slot.
    await revokeApiToken(actor, tenant.org.id, created[0]!.apiToken.id);
    await createApiToken(actor, input(tenant));
    await expect(createApiToken(actor, input(tenant))).rejects.toThrow();
  });

  it("does not count expired tokens, and stops counting at exactly expiresAt", async () => {
    const tenant = await newTenant();
    const actor = tenant.actors.member;
    const start = new Date("2031-06-01T00:00:00.000Z");
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(start);

    for (let i = 0; i < 5; i += 1) {
      await createApiToken(actor, input(tenant, { expiresInDays: 1 }));
    }
    await expect(createApiToken(actor, input(tenant))).rejects.toThrow();

    vi.setSystemTime(new Date(start.getTime() + DAY_MS - 1));
    await expect(createApiToken(actor, input(tenant))).rejects.toThrow();

    vi.setSystemTime(new Date(start.getTime() + DAY_MS));
    await createApiToken(actor, input(tenant));
  });

  it("holds the cap under concurrent creation", async () => {
    const tenant = await newTenant();

    const results = await Promise.allSettled(
      Array.from({ length: 8 }, () => createApiToken(tenant.actors.member, input(tenant))),
    );

    expect(results.filter((r) => r.status === "fulfilled")).toHaveLength(5);
    expect(await listApiTokens(tenant.actors.member, tenant.org.id)).toHaveLength(5);
  });

  it("does not count another organization's tokens", async () => {
    const tenant = await newTenant();
    const other = await newTenant();
    // The same person is a member of both organizations.
    await memberRepo.insertMember(other.org.id, tenant.userIds.member, "member", null);
    const inOther: Actor = { ...tenant.actors.member, orgId: other.org.id };

    for (let i = 0; i < 5; i += 1) {
      await createApiToken(tenant.actors.member, input(tenant));
    }
    await createApiToken(inOther, input(other));
  });
});

describe("listApiTokens", () => {
  it("lists the actor's own tokens by default, newest first, revoked and expired included", async () => {
    const tenant = await newTenant();
    const actor = tenant.actors.member;
    const start = new Date("2032-01-01T00:00:00.000Z");
    vi.useFakeTimers({ toFake: ["Date"] });

    vi.setSystemTime(start);
    const first = await createApiToken(actor, input(tenant, { name: "first", expiresInDays: 1 }));
    vi.setSystemTime(new Date(start.getTime() + 1000));
    const second = await createApiToken(actor, input(tenant, { name: "second" }));
    vi.setSystemTime(new Date(start.getTime() + 2000));
    const third = await createApiToken(actor, input(tenant, { name: "third" }));
    await createApiToken(tenant.actors.admin, input(tenant, { name: "someone else's" }));
    await revokeApiToken(actor, tenant.org.id, second.apiToken.id);

    // `first` has expired by now.
    vi.setSystemTime(new Date(start.getTime() + 2 * DAY_MS));

    const listed = await listApiTokens(actor, tenant.org.id);
    expect(listed.map((t) => t.id)).toEqual([
      third.apiToken.id,
      second.apiToken.id,
      first.apiToken.id,
    ]);
    expect(listed[1]?.revokedAt).not.toBeNull();
  });

  it("orders tokens created in the same instant by creation order", async () => {
    const tenant = await newTenant();
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2032-03-01T00:00:00.000Z"));

    const ids: string[] = [];
    for (let i = 0; i < 4; i += 1) {
      ids.push((await createApiToken(tenant.actors.member, input(tenant))).apiToken.id);
    }

    const listed = await listApiTokens(tenant.actors.member, tenant.org.id);
    expect(listed.map((t) => t.id)).toEqual([...ids].reverse());
  });

  it("rejects another organization's id", async () => {
    const tenant = await newTenant();
    const other = await newTenant();

    await expect(
      listApiTokens(tenant.actors.admin, other.org.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("lets only admins and owners list another user's tokens", async () => {
    const tenant = await newTenant();
    const { apiToken } = await createApiToken(tenant.actors.member, input(tenant));

    for (const role of ["viewer", "member"] as const) {
      await expect(
        listApiTokens(tenant.actors[role], tenant.org.id, tenant.userIds.owner),
      ).rejects.toBeInstanceOf(PermissionDeniedError);
    }
    for (const role of ["admin", "owner"] as const) {
      const listed = await listApiTokens(tenant.actors[role], tenant.org.id, tenant.userIds.member);
      expect(listed.map((t) => t.id)).toEqual([apiToken.id]);
    }
    // Listing your own explicitly is not "someone else's".
    expect(
      await listApiTokens(tenant.actors.viewer, tenant.org.id, tenant.userIds.viewer),
    ).toEqual([]);
  });
});

describe("revokeApiToken", () => {
  it("revokes the caller's own token and audits it", async () => {
    const tenant = await newTenant();
    const { apiToken } = await createApiToken(tenant.actors.viewer, input(tenant));

    const revoked = await revokeApiToken(tenant.actors.viewer, tenant.org.id, apiToken.id);

    expect(revoked.revokedAt).toEqual(expect.any(String));
    expect(revoked).toEqual({ ...apiToken, revokedAt: revoked.revokedAt });

    const rows = await activityRepo.listActivityForSubject(tenant.org.id, "api_token", apiToken.id);
    expect(rows.map((r) => r.action).sort()).toEqual(["api_token.created", "api_token.revoked"]);
    const row = rows.find((r) => r.action === "api_token.revoked");
    expect(row).toMatchObject({ actorId: tenant.userIds.viewer, subjectId: apiToken.id });
  });

  it("lets admins and owners revoke another user's token, and nobody else", async () => {
    const tenant = await newTenant();
    const mine = await createApiToken(tenant.actors.member, input(tenant));
    const theirs = await createApiToken(tenant.actors.owner, input(tenant));

    await expect(
      revokeApiToken(tenant.actors.viewer, tenant.org.id, mine.apiToken.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await revokeApiToken(tenant.actors.admin, tenant.org.id, mine.apiToken.id);
    await revokeApiToken(tenant.actors.owner, tenant.org.id, theirs.apiToken.id);

    const rows = await activityRepo.listActivityForSubject(
      tenant.org.id,
      "api_token",
      mine.apiToken.id,
    );
    expect(rows.find((r) => r.action === "api_token.revoked")?.actorId).toBe(
      tenant.userIds.admin,
    );
  });

  it("rejects another organization's id and unknown token ids", async () => {
    const tenant = await newTenant();
    const other = await newTenant();
    const foreign = await createApiToken(other.actors.owner, input(other));

    await expect(
      revokeApiToken(tenant.actors.owner, other.org.id, foreign.apiToken.id),
    ).rejects.toBeInstanceOf(TenantScopeError);

    // A real token id, but not in the actor's organization.
    await expect(
      revokeApiToken(tenant.actors.owner, tenant.org.id, foreign.apiToken.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      revokeApiToken(tenant.actors.owner, tenant.org.id, "missing"),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("is idempotent: the original revokedAt is kept and nothing more is audited", async () => {
    const tenant = await newTenant();
    const { apiToken } = await createApiToken(tenant.actors.member, input(tenant));
    vi.useFakeTimers({ toFake: ["Date"] });

    vi.setSystemTime(new Date("2033-01-01T00:00:00.000Z"));
    const first = await revokeApiToken(tenant.actors.member, tenant.org.id, apiToken.id);
    vi.setSystemTime(new Date("2033-01-02T00:00:00.000Z"));
    const second = await revokeApiToken(tenant.actors.admin, tenant.org.id, apiToken.id);

    expect(first.revokedAt).toBe("2033-01-01T00:00:00.000Z");
    expect(second).toEqual(first);

    const rows = await activityRepo.listActivityForSubject(tenant.org.id, "api_token", apiToken.id);
    expect(rows.filter((r) => r.action === "api_token.revoked")).toHaveLength(1);
  });
});

describe("authenticateApiToken", () => {
  it("resolves the owner as a viewer for a read token", async () => {
    const tenant = await newTenant();
    const { token } = await createApiToken(tenant.actors.admin, input(tenant, { scope: "read" }));

    expect(await authenticateApiToken(token)).toEqual({
      userId: tenant.userIds.admin,
      orgId: tenant.org.id,
      role: "viewer",
    });
  });

  it("resolves a write token with the member's current role", async () => {
    const tenant = await newTenant();
    const { token } = await createApiToken(tenant.actors.member, input(tenant, { scope: "write" }));

    expect((await authenticateApiToken(token))?.role).toBe("member");

    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    await updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member!.id,
      role: "admin",
    });
    expect((await authenticateApiToken(token))?.role).toBe("admin");

    await updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member!.id,
      role: "viewer",
    });
    expect((await authenticateApiToken(token))?.role).toBe("viewer");
  });

  it("records lastUsedAt on success only", async () => {
    const tenant = await newTenant();
    const actor = tenant.actors.member;
    const { token, apiToken } = await createApiToken(actor, input(tenant));
    vi.useFakeTimers({ toFake: ["Date"] });

    vi.setSystemTime(new Date("2034-05-05T05:05:05.000Z"));
    await authenticateApiToken(token);
    expect((await listApiTokens(actor, tenant.org.id))[0]?.lastUsedAt).toBe(
      "2034-05-05T05:05:05.000Z",
    );

    await revokeApiToken(actor, tenant.org.id, apiToken.id);
    vi.setSystemTime(new Date("2034-05-06T00:00:00.000Z"));
    expect(await authenticateApiToken(token)).toBeNull();
    expect((await listApiTokens(actor, tenant.org.id))[0]?.lastUsedAt).toBe(
      "2034-05-05T05:05:05.000Z",
    );
  });

  it("resolves null for unknown, revoked and expired tokens (expiry is exact)", async () => {
    const tenant = await newTenant();
    const actor = tenant.actors.member;
    const start = new Date("2035-01-01T00:00:00.000Z");
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(start);

    expect(await authenticateApiToken("tfk_nope")).toBeNull();
    expect(await authenticateApiToken("")).toBeNull();

    const live = await createApiToken(actor, input(tenant, { expiresInDays: 1 }));
    const revoked = await createApiToken(actor, input(tenant));
    await revokeApiToken(actor, tenant.org.id, revoked.apiToken.id);
    expect(await authenticateApiToken(revoked.token)).toBeNull();

    vi.setSystemTime(new Date(start.getTime() + DAY_MS - 1));
    expect(await authenticateApiToken(live.token)).not.toBeNull();

    vi.setSystemTime(new Date(start.getTime() + DAY_MS));
    expect(await authenticateApiToken(live.token)).toBeNull();
  });

  it("resolves null once the user is no longer an active member", async () => {
    const tenant = await newTenant();
    const { token } = await createApiToken(tenant.actors.member, input(tenant));
    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);

    await memberRepo.archiveMember(tenant.org.id, member!.id);

    expect(await authenticateApiToken(token)).toBeNull();
  });

  it("resolves null once the organization has been deleted", async () => {
    const tenant = await newTenant();
    const { token } = await createApiToken(tenant.actors.owner, input(tenant));
    expect(await authenticateApiToken(token)).not.toBeNull();

    await orgRepo.archiveOrg(tenant.org.id);

    expect(await authenticateApiToken(token)).toBeNull();
  });
});

describe("audit trail", () => {
  it("records creation and revocation with the acting user and no secret or hash", async () => {
    const tenant = await newTenant();
    const { token, apiToken } = await createApiToken(
      tenant.actors.member,
      input(tenant, { name: "audited", scope: "write" }),
    );
    await revokeApiToken(tenant.actors.admin, tenant.org.id, apiToken.id);

    const rows = await auditRows(tenant);
    expect(rows).toHaveLength(2);
    expect(rows.map((r) => r.action).sort()).toEqual(["api_token.created", "api_token.revoked"]);
    for (const row of rows) {
      expect(row.subjectKind).toBe("api_token");
      expect(row.subjectId).toBe(apiToken.id);
    }
    expect(rows.find((r) => r.action === "api_token.created")?.actorId).toBe(tenant.userIds.member);
    expect(rows.find((r) => r.action === "api_token.revoked")?.actorId).toBe(tenant.userIds.admin);

    const dump = JSON.stringify(rows);
    expect(dump).not.toContain(token);
    expect(dump).not.toContain(hashToken(token));
    expect(dump).not.toContain(apiToken.prefix);
  });

  it("accepts the new actions and subject kind in audit-log filters", async () => {
    const tenant = await newTenant();
    const parsed = activityFilterSchema.parse({
      orgId: tenant.org.id,
      action: ["api_token.created", "api_token.revoked"],
      subjectKind: "api_token",
    });
    expect(parsed.action).toEqual(["api_token.created", "api_token.revoked"]);
    expect(parsed.subjectKind).toBe("api_token");
  });
});

describe("member removal", () => {
  it("revokes the removed member's unrevoked tokens, audited with the remover as actor", async () => {
    const tenant = await newTenant();
    const other = await newTenant();
    const userId = tenant.userIds.member;
    await memberRepo.insertMember(other.org.id, userId, "member", null);
    const inOther: Actor = { userId, orgId: other.org.id, role: "member" };

    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2036-01-01T00:00:00.000Z"));
    const live = await createApiToken(tenant.actors.member, input(tenant, { name: "live" }));
    const expiring = await createApiToken(
      tenant.actors.member,
      input(tenant, { name: "expired", expiresInDays: 1 }),
    );
    const already = await createApiToken(tenant.actors.member, input(tenant, { name: "already" }));
    const elsewhere = await createApiToken(inOther, input(other));

    vi.setSystemTime(new Date("2036-01-02T00:00:00.000Z"));
    await revokeApiToken(tenant.actors.member, tenant.org.id, already.apiToken.id);

    vi.setSystemTime(new Date("2036-01-03T00:00:00.000Z"));
    const member = await memberRepo.findMember(tenant.org.id, userId);
    await removeMember(tenant.actors.admin, { orgId: tenant.org.id, memberId: member!.id });

    const listed = await listApiTokens(tenant.actors.admin, tenant.org.id, userId);
    const byId = new Map(listed.map((t) => [t.id, t]));
    expect(byId.get(live.apiToken.id)?.revokedAt).toBe("2036-01-03T00:00:00.000Z");
    expect(byId.get(expiring.apiToken.id)?.revokedAt).toBe("2036-01-03T00:00:00.000Z");
    expect(byId.get(already.apiToken.id)?.revokedAt).toBe("2036-01-02T00:00:00.000Z");

    // Tokens in other organizations are untouched.
    const otherListed = await listApiTokens(other.actors.admin, other.org.id, userId);
    expect(otherListed.map((t) => t.revokedAt)).toEqual([null]);
    expect(otherListed[0]?.id).toBe(elsewhere.apiToken.id);

    const revokedRows = (await auditRows(tenant)).filter((r) => r.action === "api_token.revoked");
    expect(revokedRows.map((r) => r.subjectId).sort()).toEqual(
      [live.apiToken.id, expiring.apiToken.id, already.apiToken.id].sort(),
    );
    for (const row of revokedRows) {
      if (row.subjectId === already.apiToken.id) {
        expect(row.actorId).toBe(userId);
      } else {
        expect(row.actorId).toBe(tenant.userIds.admin);
      }
    }
    expect(await auditRows(other, other.actors.admin)).toHaveLength(1);
  });

  it("looks up the removed user without touching other users' tokens", async () => {
    const tenant = await newTenant();
    const bystander = await createApiToken(tenant.actors.owner, input(tenant));
    await createApiToken(tenant.actors.viewer, input(tenant));

    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    await removeMember(tenant.actors.admin, { orgId: tenant.org.id, memberId: member!.id });

    const [still] = await listApiTokens(tenant.actors.owner, tenant.org.id);
    expect(still?.id).toBe(bystander.apiToken.id);
    expect(still?.revokedAt).toBeNull();
    expect(await userRepo.findUserById(tenant.userIds.viewer)).not.toBeNull();
  });
});

